function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) { return v === true || v === 'true'; }
// Vollstaendiger Post+Bild-Ersatz (Nutzerentscheidung 2026-08-30, Ausbaustufe des vorherigen
// reinen Backfill-Tools) - unconditional fuer JEDEN bereits auf diePARTEI veroeffentlichten
// Vorgang mit einem echten aktuellen Bild, nicht nur bei fehlendem Beitragsbild.
return $input.all().filter(item => {
  const j = item.json || {};
  if (!safeBool(j.wordpressGoslarPosted)) return false;
  if (!safeStr(j.wordpressGoslarPostId)) return false;
  if (!safeStr(j.imageFinalPath)) return false;
  if (!safeStr(j.websiteArticle)) return false;
  if (!safeStr(j.vorgangKey)) return false;
  return true;
});

const now = Date.now();
const owner = `ALLRIS_Einmalig_WordPressGoslar_Post_Bild_Ersetzen:${$execution.id}`;
return items.map(item => {
  const j = item.json || {};
  const oldOwner = String(j.claim_owner || '').trim();
  const expires = Date.parse(String(j.claim_expires_at || ''));
  const eligible = !oldOwner || !Number.isFinite(expires) || expires <= now;
  return { json: {
    ...j,
    claimAction: 'acquire',
    claimOwner: owner,
    claimStage: 'publication',
    leaseMinutes: 30,
    expectedClaimOwner: j.claim_owner ?? null,
    expectedClaimExpiresAt: j.claim_expires_at ?? null,
    needsClaimAttempt: eligible
  } };
});

const idx = $itemIndex;
const ctx = $('Nur bestaetigte Claims').itemMatching(idx).json;
const resp = $json || {};
const postExists = !!(resp && resp.id && !resp.error);
const oldFeaturedMedia = postExists ? Number(resp.featured_media || 0) : 0;
return { json: { ...ctx, _postExists: postExists, _oldFeaturedMedia: oldFeaturedMedia } };

const idx = $itemIndex;
const ctx = $('Werte Live-Post aus').itemMatching(idx).json;
return { json: { ...ctx } };

const idx = $itemIndex;
const ctx = $('Werte Live-Post aus').itemMatching(idx).json;
return { json: { ...ctx } };

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function esc(v) { return safeStr(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function slugify(v) {
  return safeStr(v).toLowerCase()
    .replace(/[ä]/g,'ae').replace(/[ö]/g,'oe').replace(/[ü]/g,'ue').replace(/[ß]/g,'ss')
    .replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').substring(0,80);
}
function uniqueTags(tags) {
  return Array.from(new Set(
    tags.map(t => safeStr(t)).filter(Boolean).filter(t => t.length <= 50)
  ));
}
function topicTagsFromText(text) {
  const t = String(text || '').toLowerCase();
  const tags = [];
  function hasAny(words) { return words.some(w => t.indexOf(String(w).toLowerCase()) !== -1); }
  if (hasAny(['bus','stadtbus','linie','liniennetz','haltestelle','oepnv','öpnv','fahrplan','verkehr','umleitung','sperrung','radweg','parkplatz'])) tags.push('Verkehr','ÖPNV');
  if (hasAny(['bauschutt','baustelle','bauzaun','abbruch','abriss','baustellensicherheit','absperrung'])) tags.push('Baustelle','Sicherheit');
  if (hasAny(['stadtbus','haltestelle','fahrgast','fahrgäste','linienfuehrung','schuljahresbeginn'])) tags.push('Stadtbus');
  if (hasAny(['denkmalschutz','altstadt','unesco','welterbe','denkmal','sanierung','historisch'])) tags.push('Altstadt','Denkmalschutz','UNESCO');
  if (hasAny(['haushalt','kosten','finanz','haushaltsmittel','foerderung','investition','gebühr','zuschuss'])) tags.push('Haushalt','Finanzen','Kosten');
  if (hasAny(['schule','schüler','schülerinnen','kita','kindergarten','bildung','jugend','schulweg'])) tags.push('Schule','Bildung');
  if (hasAny(['mülleimer','papierkorb','abfall','bänke','bank','sitzbank','stadtbild','aufenthaltsqualität','innenstadt','standort'])) tags.push('Stadtbild','Aufenthaltsqualität');
  if (hasAny(['digitalisierung','software','open source','verwaltung','transparenz','daten','portal','online','it'])) tags.push('Verwaltung','Digitalisierung','Transparenz');
  if (hasAny(['energie','wärme','wärmeplanung','klima','klimaschutz','heizung','wärmenetz','fernwärme'])) tags.push('Energie','Wärmeplanung','Klimaschutz');
  if (hasAny(['barriere','barrierefreiheit','inklusion','teilhabe','behinderung','senioren','ältere menschen'])) tags.push('Barrierefreiheit','Inklusion');
  if (hasAny(['wahl','wahlwerbung','plakat','plakate','sondernutzung','wahlvorschlag','kandidierende','einzelbewerbung','chancengleichheit'])) tags.push('Wahl','Wahlwerbung','Chancengleichheit');
  return tags;
}
const ALWAYS_TAGS = ['Goslar', 'MeinGoslar', 'UnserKlüngelKannMehr'];

const j = $json;
const title = safeStr(j.websiteHeadline) || (safeStr(j.vorgangsnummer) + ' - ' + safeStr(j.title));
const paragraphs = safeStr(j.websiteArticle).split(/\n\s*\n/).filter(Boolean).map(p => '<p>' + esc(p).replace(/\n/g, '<br>') + '</p>').join('\n');
const footer = '<p><em>Vorgangsnummer: ' + esc(j.vorgangsnummer) + ' | <a href="' + esc(j.allrisUrl) + '">Original bei ALLRIS</a></em></p>';
const content = paragraphs + '\n' + footer;
const slug = slugify(safeStr(j.vorgangsnummer) + ' ' + title);
const hasImage = !!safeStr(j.imageFinalPath);

const combinedTagText = [title, j.vorgangsnummer, j.thema, j.betroffene, j.kostenHaushalt, j.buergerwirkung, j.websiteArticle].map(safeStr).join(' ');
const wpTags = uniqueTags([...ALWAYS_TAGS, ...topicTagsFromText(combinedTagText), ...(j.fachdienst ? [j.fachdienst] : [])]);

return {
  json: {
    ...j,
    wpTitle: title,
    wpContent: content,
    wpSlug: slug,
    hasImage: hasImage,
    wpTags: wpTags
  }
};

const current = $('Baue Post-Body').first().json;
const wpTags = Array.isArray(current.wpTags) ? current.wpTags : [];

function norm(v) { return String(v || '').trim().toLowerCase(); }

const rawExisting = $input.all().map(i => i.json);
let existingList = rawExisting;
if (rawExisting.length === 1 && Array.isArray(rawExisting[0])) {
  existingList = rawExisting[0];
}

const existingByName = new Map();
for (const t of existingList) {
  if (t && t.name) existingByName.set(norm(t.name), t.id);
}

const resolvedTagIds = [];
const missingTagNames = [];
const seen = new Set();

for (const rawName of wpTags) {
  const name = String(rawName || '').trim();
  if (!name) continue;
  const n = norm(name);
  if (seen.has(n)) continue;
  seen.add(n);
  if (existingByName.has(n)) {
    resolvedTagIds.push(existingByName.get(n));
  } else {
    missingTagNames.push(name);
  }
}

return [{
  json: {
    ...current,
    resolvedTagIds,
    missingTagNames
  }
}];

const current = $input.first().json;
const missing = Array.isArray(current.missingTagNames) ? current.missingTagNames : [];

if (missing.length === 0) {
  return [{ json: { tagName: '', isSentinel: true } }];
}

return missing.map(name => ({ json: { tagName: name, isSentinel: false } }));

const original = $('Ermittle fehlende Tags').first().json;
const resolvedTagIds = Array.isArray(original.resolvedTagIds) ? original.resolvedTagIds : [];

function extractTagId(j) {
  if (!j) return null;
  if (j.id) return j.id;
  if (j.body && j.body.id) return j.body.id;
  if (j.data && j.data.term_id) return j.data.term_id;
  if (j.error && j.error.data && j.error.data.term_id) return j.error.data.term_id;
  return null;
}

const newTagIds = [];
for (const item of $input.all()) {
  const id = extractTagId(item.json || {});
  if (id) newTagIds.push(id);
}

return [{
  json: {
    ...original,
    wordpressTagIds: [...new Set([...resolvedTagIds, ...newTagIds])]
  }
}];

const idx = $itemIndex;
const original = $('Baue finale Tag-Liste').itemMatching(idx).json;
const responses = $input.all().map(item => item.json || {});

function safe(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function isLookupError(j) {
  return Boolean(j.error || j.name === 'NodeApiError' || Number(j.statusCode || j.status || 0) >= 400);
}

const lookupError = responses.find(isLookupError);
const expectedSlug = safe(original.wpSlug);
const existingPost = responses.find(j =>
  !isLookupError(j) && Boolean(j.id) && safe(j.slug) === expectedSlug
);
const lookupErrorMessage = lookupError
  ? (safe(lookupError.error?.message) || safe(lookupError.message) || 'WordPress-Slug-Suche der Partei-Webseite fehlgeschlagen.')
  : '';

return [{
  json: {
    ...original,
    _partySlugExists: Boolean(existingPost),
    _partySlugLookupOk: !lookupError,
    _existingId: existingPost?.id || '',
    _existingLink: existingPost?.link || '',
    error: lookupError ? { message: lookupErrorMessage } : undefined
  }
}];

const idx = $itemIndex;
const original = $('IF Bild vorhanden?').itemMatching(idx).json;
const item = $input.item;
const downloadResult = item.json;
const error = downloadResult && downloadResult.error ? downloadResult.error : undefined;
return { json: { ...original, error }, binary: item.binary };

const idx = $itemIndex;
const original = $('Baue Post-Body').itemMatching(idx).json;
const uploadResult = $('Upload Media zu Partei-Webseite').itemMatching(idx).json;
const confirmResult = $json;
function extractErrorText(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') return String(v.message || v.description || v.error || JSON.stringify(v));
  return String(v);
}
const mediaId = uploadResult && uploadResult.id ? uploadResult.id : null;
const mediaUrl = (confirmResult && confirmResult.source_url)
  || (confirmResult && confirmResult.guid && confirmResult.guid.rendered)
  || (uploadResult && uploadResult.source_url)
  || (uploadResult && uploadResult.guid && uploadResult.guid.rendered)
  || null;
const mediaUploadError = mediaId ? '' : (
  extractErrorText(uploadResult && uploadResult.error) ||
  extractErrorText(uploadResult && uploadResult.message) ||
  'Medien-Upload zur Partei-Webseite lieferte keine Media-ID (Ursache unbekannt).'
);
return { json: { ...original, wpFeaturedMediaId: mediaId, wpFeaturedMediaUrl: mediaUrl, wpMediaUploadError: mediaUploadError } };

const idx = $itemIndex;
const original = $('Baue Post-Body').itemMatching(idx).json;
let mediaContext = {};
try {
  mediaContext = $('Stelle Kontext nach Media-Upload wieder her').itemMatching(idx).json || {};
} catch (e) {
  mediaContext = {};
}
const resp = $json || {};
const postId = resp.id || resp.data?.id || null;
const postLink = resp.link || resp.data?.link || '';
const postError = resp.error?.message || resp.error || resp.message || '';
return {
  json: {
    ...original,
    wpFeaturedMediaId: mediaContext.wpFeaturedMediaId ?? original.wpFeaturedMediaId ?? null,
    wpFeaturedMediaUrl: mediaContext.wpFeaturedMediaUrl ?? original.wpFeaturedMediaUrl ?? '',
    wpMediaUploadError: mediaContext.wpMediaUploadError ?? original.wpMediaUploadError ?? '',
    wpPostId: postId,
    wpPostLink: postLink,
    wpPostSuccess: !postError && !!postId,
    wpPostError: postError ? String(postError) : ''
  }
};

const vorgangKey = String($json.vorgangKey || '').trim();
const id = $json.id;
if (!vorgangKey) throw new Error('[Claim Release] vorgangKey fehlt.');
if (!id) throw new Error('[Claim Release] id fehlt.');
return [{ json: { id, vorgangKey, claimAction: 'release', claimOwner: `ALLRIS_Einmalig_WordPressGoslar_Post_Bild_Ersetzen:${$execution.id}` } }];

const idx = $itemIndex;
const ctx = $('Stelle Kontext nach Bildladen wieder her').itemMatching(idx).json;
return { json: { ...ctx, wpPostError: 'Bild-Download fehlgeschlagen: ' + JSON.stringify(ctx.error || {}).slice(0,300) } };
